use super::*;
use aspis_statement::pool_v1::*;
fn digest()->aspis_statement::Digest{core::array::from_fn(|_|aspis_core::field::M31(kani::any()))}
fn any_PoolV1PrivateTransferPublicV1()->PoolV1PrivateTransferPublicV1{PoolV1PrivateTransferPublicV1{pool:kani::any(),deployment_domain:kani::any(),anchor_sequence:kani::any(),anchor_root:digest(),nullifier:digest(),asset_id:aspis_core::field::M31(kani::any()),recipient_commitment:digest(),change_commitment:digest()}}
fn any_PoolV1WithdrawalPublicV1()->PoolV1WithdrawalPublicV1{PoolV1WithdrawalPublicV1{pool:kani::any(),deployment_domain:kani::any(),anchor_sequence:kani::any(),anchor_root:digest(),nullifier:digest(),asset_id:aspis_core::field::M31(kani::any()),amount:kani::any(),destination_token_account:kani::any(),change_commitment:digest()}}
#[kani::proof]
#[kani::unwind(34)]
#[kani::stub(crate::registry::authenticate_verifier_selection_v1,crate::registry::NFV_Oracle::authenticate)]
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NFO_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NFO_KMX::KMX_copy_from_slice)]
fn association(){
 let selected=Pubkey::new_from_array(kani::any());
 let base=selected.to_bytes();
 let loader=match kani::any::<u8>()%3{0=>bpf_loader::id(),1=>bpf_loader_upgradeable::id(),_=>loader_v4::id()};let owner=Pubkey::new_from_array(kani::any());
 let mut key0=base;key0[0]^=0;let key0=Pubkey::new_from_array(key0);let mut lam0:u64=kani::any();let mut data0=[];
 let info0=AccountInfo::new(&key0,false,false,&mut lam0,&mut data0,&loader,true,kani::any());
 let key1:[u8;32]=kani::any();let key1=Pubkey::new_from_array(key1);let mut lam1:u64=kani::any();let mut data1=[];
 let proof_owner=Pubkey::new_from_array(kani::any());let info1=AccountInfo::new(&key1,false,false,&mut lam1,&mut data1,&proof_owner,false,kani::any());
 let key2:[u8;32]=kani::any();let key2=Pubkey::new_from_array(key2);let mut lam2:u64=kani::any();let mut data2=[];
 let info2=AccountInfo::new(&key2,false,false,&mut lam2,&mut data2,&selected,false,kani::any());
 let key3:[u8;32]=kani::any();let key3=Pubkey::new_from_array(key3);let mut lam3:u64=kani::any();let mut data3=[];
 let info3=AccountInfo::new(&key3,kani::any(),kani::any(),&mut lam3,&mut data3,&owner,kani::any(),kani::any());
 let key4:[u8;32]=kani::any();let key4=Pubkey::new_from_array(key4);let mut lam4:u64=kani::any();let mut data4=[];
 let info4=AccountInfo::new(&key4,kani::any(),kani::any(),&mut lam4,&mut data4,&owner,kani::any(),kani::any());
 let key5:[u8;32]=kani::any();let key5=Pubkey::new_from_array(key5);let mut lam5:u64=kani::any();let mut data5=[];
 let info5=AccountInfo::new(&key5,kani::any(),kani::any(),&mut lam5,&mut data5,&owner,kani::any(),kani::any());
 let key6:[u8;32]=kani::any();let key6=Pubkey::new_from_array(key6);let mut lam6:u64=kani::any();let mut data6=[];
 let registry_owner6=Pubkey::new_from_array(kani::any());let info6=AccountInfo::new(&key6,kani::any(),kani::any(),&mut lam6,&mut data6,&registry_owner6,kani::any(),kani::any());
 let key7:[u8;32]=kani::any();let key7=Pubkey::new_from_array(key7);let mut lam7:u64=kani::any();let mut data7=[];
 let registry_owner7=Pubkey::new_from_array(kani::any());let info7=AccountInfo::new(&key7,kani::any(),kani::any(),&mut lam7,&mut data7,&registry_owner7,kani::any(),kani::any());

 kani::assume(key1!=selected&&key2!=selected&&key2!=key1&&key2!=key3&&key2!=key4&&key2!=key5&&key2!=key6&&key2!=key7);

 let public=if kani::any(){PoolV1PairForestTerminalPaymentV1::PrivateTransfer(any_PoolV1PrivateTransferPublicV1())}else{PoolV1PairForestTerminalPaymentV1::Withdrawal(any_PoolV1WithdrawalPublicV1())};
 let request=PoolV1PairForestTerminalRequestV1{pool_program:owner.to_bytes(),verifier_profile:kani::any(),verifier_release:kani::any(),public};
 let raw:[u8;320]=kani::any();let bytes:Box<[u8]>=Box::new(raw);let pointer=bytes.as_ptr();let j:usize=kani::any();kani::assume(j<320);let byte=bytes[j];
 let policy=VerifierPolicyV1{flags:kani::any(),registry_program:kani::any(),registry_authority:kani::any(),policy_binding:kani::any()};
 let actual=plan_pair_forest_terminal_dispatch_with_bytes_v1(&owner,&info3,&info4,&info5,&policy,&[info6,info7],&info0,&info1,Some(&info2),&request,kani::any(),bytes.into_vec());
 if let Ok(plan)=actual{
  assert!(plan.selected_verifier==selected);
  assert!(plan.request_bytes.len()==320&&plan.request_bytes.as_ptr()==pointer);
  assert!(plan.request_bytes[j]==byte);
 }
}

