use super::*;
pub(crate) fn authenticate(_: &Pubkey,_:&VerifierPolicyV1,_:&[AccountInfo<'_>],_:VerifierSelectionV1,_:u64)->Result<AuthenticatedVerifierSelectionV1,ProgramError>{
 if kani::any(){Err(ProgramError::from(kani::any::<u64>()))}else{Ok(AuthenticatedVerifierSelectionV1{
 policy:VerifierPolicyV1{flags:kani::any(),registry_program:kani::any(),registry_authority:kani::any(),policy_binding:kani::any()},pool:kani::any(),verifier_program:kani::any(),profile_binding:kani::any(),release_binding:kani::any(),statement_version:kani::any(),registry_generation:kani::any(),expected_verifier_loader:kani::any(),authenticated_at_slot:kani::any()})}
}
